+static bool mxfp4_down_q80_compat_batch_requested(const char *name, ggml_type type) {
+    const char *env = std::getenv("GGML_MOE_STREAM_DOWN_Q80_COMPAT_BATCH");
+    if (!env || !env[0] || env[0] == '0') return false;
+    if (std::strcmp(env, "2") != 0 && std::strcmp(env, "rowtile") != 0) return false;
+    if (type != GGML_TYPE_MXFP4 || !name || !std::strstr(name, "ffn_down_exps")) return false;
+    const char *target = std::getenv("GGML_MOE_STREAM_DOWN_Q80_COMPAT_TENSOR");
+    return !target || !target[0] || std::strstr(name, target) != nullptr;
+}
+
+static __device__ __forceinline__ int moe_stream_batch_mxfp4_value_dev(int q) {
+    switch (q & 0x0F) {
+        case 0x0: return 0;
+        case 0x1: return 1;
+        case 0x2: return 2;
+        case 0x3: return 3;
+        case 0x4: return 4;
+        case 0x5: return 6;
+        case 0x6: return 8;
+        case 0x7: return 12;
+        case 0x8: return 0;
+        case 0x9: return -1;
+        case 0xA: return -2;
+        case 0xB: return -3;
+        case 0xC: return -4;
+        case 0xD: return -6;
+        case 0xE: return -8;
+        default:  return -12;
+    }
+}
+
+static __device__ __forceinline__ float moe_stream_batch_q80_cpu_compat_hsum8(
+        const float acc1[8], const float acc2[8]) {
+    const float x0 = acc1[0] + acc2[0];
+    const float x1 = acc1[1] + acc2[1];
+    const float x2 = acc1[2] + acc2[2];
+    const float x3 = acc1[3] + acc2[3];
+    const float x4 = acc1[4] + acc2[4];
+    const float x5 = acc1[5] + acc2[5];
+    const float x6 = acc1[6] + acc2[6];
+    const float x7 = acc1[7] + acc2[7];
+    const float r0 = x4 + x0;
+    const float r1 = x5 + x1;
+    const float r2 = x6 + x2;
+    const float r3 = x7 + x3;
+    return (r0 + r2) + (r1 + r3);
+}
+
+static __device__ __forceinline__ int moe_stream_batch_q80_cpu_compat_one_lane(
+        const block_mxfp4 &x,
+        const block_q8_0 &y,
+        int lane) {
+    const int group = lane & 3;
+    const bool high = lane >= 4;
+    int sum = 0;
+#pragma unroll
+    for (int r = 0; r < 4; ++r) {
+        const int j = group * 4 + r;
+        const uint8_t q = x.qs[j];
+        const int q4 = high ? (q >> 4) : (q & 0x0F);
+        const int q8_idx = high ? j + QK_MXFP4/2 : j;
+        sum += y.qs[q8_idx] * moe_stream_batch_mxfp4_value_dev(q4);
+    }
+    return sum;
+}
+
+static __global__ void moe_stream_batch_q80_mxfp4_rowtile_kernel(
+        const char * const * __restrict__ src0_rows,
+        size_t nb01,
+        const char * __restrict__ q80,
+        size_t q80_row_size,
+        int64_t ne00,
+        int rows,
+        int cols,
+        float * __restrict__ out) {
+    constexpr int tile_cols = 16;
+    __shared__ block_q8_0 sh_y[2];
+
+    const int row = (int) blockIdx.x;
+    const int tile_col0 = (int) blockIdx.y * tile_cols;
+    const int col_group = threadIdx.x >> 4;
+    const int sublane = threadIdx.x & 15;
+    const int lane = threadIdx.x & 31;
+    const int col = tile_col0 + col_group;
+    const bool active = row < rows && col < cols;
+    const int base_lane = (lane & 16) ? 16 : 0;
+    const uint32_t half_mask = (lane & 16) ? 0xffff0000u : 0x0000ffffu;
+    const int lane8 = sublane & 7;
+
+    const char *src0 = row < rows ? src0_rows[row] : nullptr;
+    const block_mxfp4 *x_raw = (const block_mxfp4 *) (active ? src0 + (size_t) col * nb01 : nullptr);
+    const block_q8_0 *y = (const block_q8_0 *) (q80 + (size_t) row * q80_row_size);
+    const int64_t nb = ne00 / QK_MXFP4;
+
+    float acc = 0.0f;
+    int64_t ib = 0;
+    for (; ib + 1 < nb; ib += 2) {
+        char *sh_bytes = (char *) sh_y;
+        const char *y_bytes = (const char *) (y + ib);
+        for (int off = (int) threadIdx.x; off < (int) (2 * sizeof(block_q8_0)); off += (int) blockDim.x) {
+            sh_bytes[off] = y_bytes[off];
+        }
+        __syncthreads();
+
+        if (active) {
+            const bool second = sublane >= 8;
+            const block_mxfp4 &xb = x_raw[ib + (second ? 1 : 0)];
+            const block_q8_0 &yb = sh_y[second ? 1 : 0];
+            const int p = moe_stream_batch_q80_cpu_compat_one_lane(xb, yb, lane8);
+            const float scale = __half2float(yb.d) * (ggml_cuda_e8m0_to_fp32(xb.e) * 0.5f);
+            acc = fmaf(scale, (float) p, acc);
+        }
+        __syncthreads();
+    }
+
+    float acc1[8];
+    float acc2[8];
+#pragma unroll
+    for (int i = 0; i < 8; ++i) {
+        acc1[i] = __shfl_sync(half_mask, acc, base_lane + i);
+        acc2[i] = __shfl_sync(half_mask, acc, base_lane + 8 + i);
+    }
+
+    if (active && sublane == 0) {
+        float sum = moe_stream_batch_q80_cpu_compat_hsum8(acc1, acc2);
+        for (; ib < nb; ++ib) {
+            int sumi1 = 0;
+            int sumi2 = 0;
+            const block_mxfp4 &xb = x_raw[ib];
+#pragma unroll
+            for (int j = 0; j < QK_MXFP4/2; ++j) {
+                const uint8_t q = xb.qs[j];
+                sumi1 += y[ib].qs[j] * moe_stream_batch_mxfp4_value_dev(q & 0x0F);
+                sumi2 += y[ib].qs[j + QK_MXFP4/2] * moe_stream_batch_mxfp4_value_dev(q >> 4);
+            }
+            const float scale = __half2float(y[ib].d) * (ggml_cuda_e8m0_to_fp32(xb.e) * 0.5f);
+            sum = fmaf(scale, (float) (sumi1 + sumi2), sum);
+        }
+        out[(size_t) row * (size_t) cols + (size_t) col] = sum;
+    }
+}
